import pandas as pd

employees = pd.DataFrame({
    "emp_id": [1, 2, 3, 4],
    "name": ["Alice", "Bob", "Charlie", "Diana"],
})

salaries = pd.DataFrame({
    "emp_id": [1, 2, 3, 5],
    "salary": [70000, 65000, 80000, 90000],
})

merged = pd.merge(employees, salaries, on="emp_id", how="inner")
print(merged)
